        :root {
            --bg-color: #0a0616;
            --text-color: #ffffff;
            --accent-color: #ffaa00;
            --font-main: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
        }

        body, html {
            margin: 0;
            padding: 0;
            width: 100%;
            height: 100%;
            overflow: hidden;
            background-color: var(--bg-color);
            font-family: var(--font-main);
        }

        #canvas-container {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: 1;
        }

        /* Overlay logic: pointer-events none allows clicking the galaxy through the text */
        #hero-overlay {
            position: relative;
            z-index: 10;
            width: 100%;
            height: 100vh;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            pointer-events: none; 
            color: var(--text-color);
        }

        h1 {
            font-size: clamp(3rem, 10vw, 6rem);
            margin: 0;
            letter-spacing: -2px;
            text-transform: uppercase;
            font-weight: 900;
            background: linear-gradient(to bottom, #ffffff, #aaaaaa);
            -webkit-background-clause: text;
            -webkit-text-fill-color: transparent;
        }

        p {
            font-size: clamp(1rem, 2vw, 1.5rem);
            margin: 10px 0 30px 0;
            opacity: 0.8;
            letter-spacing: 2px;
            text-transform: uppercase;
        }

        /* Re-enable pointer events for the interactive button */
        button {
            pointer-events: auto;
            padding: 15px 40px;
            font-size: 1rem;
            font-weight: 600;
            text-transform: uppercase;
            letter-spacing: 1px;
            background: transparent;
            color: white;
            border: 2px solid rgba(255, 255, 255, 0.3);
            border-radius: 50px;
            cursor: pointer;
            transition: all 0.3s ease;
        }

        button:hover {
            background: white;
            color: var(--bg-color);
            transform: translateY(-3px);
            box-shadow: 0 10px 20px rgba(255, 255, 255, 0.1);
        }

        button:active {
            transform: translateY(-1px);
        }
    </style>
</head>
